-- An account can have more than one Cloudflare agent. The old primary key was userId.
-- Those rows keep that value as id. zone_id is the domain this setup attached, when it did.
-- Append-only: do not edit this file.
CREATE TABLE cloudflare_inbox_agent (
  id TEXT NOT NULL PRIMARY KEY,
  "userId" TEXT NOT NULL REFERENCES "user" ("id") ON DELETE CASCADE,
  cf_account_id TEXT NOT NULL,
  worker_name TEXT NOT NULL,
  d1_name TEXT NOT NULL,
  d1_id TEXT,
  public_url TEXT,
  owner_token_hash TEXT,
  host TEXT NOT NULL,
  hostname TEXT,
  status TEXT NOT NULL,
  script_tag TEXT,
  wizard_step TEXT,
  workers_subdomain TEXT,
  step_error TEXT,
  zone_id TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

INSERT INTO cloudflare_inbox_agent (
  id, "userId", cf_account_id, worker_name, d1_name, d1_id, public_url, owner_token_hash,
  host, hostname, status, script_tag, wizard_step, workers_subdomain, step_error, zone_id,
  created_at, updated_at
)
SELECT
  "userId", "userId", cf_account_id, worker_name, d1_name, d1_id, public_url, owner_token_hash,
  host, hostname, status, script_tag, wizard_step, workers_subdomain, step_error, NULL,
  created_at, updated_at
FROM cloudflare_inbox;

DROP TABLE cloudflare_inbox;
ALTER TABLE cloudflare_inbox_agent RENAME TO cloudflare_inbox;
CREATE INDEX IF NOT EXISTS cloudflare_inbox_user_idx ON cloudflare_inbox ("userId", created_at);
